const client = supabase.createClient(
    'env.get("SUPABASE_URL")', 
    'env.get("SUPABASE_APIKEY")'
)

const table = env.get("Table")
const filterProperty = env.get("Filter Property")
const filterValue = env.get("Filter Value")

if (!filterProperty){
    const { data, error } = await client
        .from(table)
        .select("*")
    msg.payload = data
} else {
    const { data, error } = await client
        .from(table)
        .select("*")
        .eq(filterProperty, filterValue)
    msg.payload = data
}

return msg

